// 共享候选：申请不解除旧责任，批准实际调用原Office账，再由原提交尾绑定真实结果。
#include "political_office_resignation_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
Status available(const WorldBundle& w){return w.catalog->political_office_resignations&&w.political_office_resignations&&w.catalog->political_successions&&w.political_successions&&w.politics_enabled()&&w.catalog->organization&&w.catalog->organization->enabled&&w.family_life_enabled()&&w.catalog->common?common_success():common_failure("PoliticalOfficeResignationProfileRequired");}
// 成功效果必须精确对上本次辞任事实，批准另带同次唯一原Organization变更。
bool actual_result(const CommitResult& r,const StableId& source,const StableId& office){if(!r.ok||!r.details)return false;const auto* e=std::get_if<PoliticsEffects>(&r.details->data);std::vector<StableId> ids{source};if(!office.empty())ids.push_back(office);return e&&valid_political_office_resignation_effect(r.kind,*e)&&e->fact_ids==ids;}
Status player(const WorldBundle& w,const StableId& actor,const PoliticalOfficeResignationCommand& c){auto v=command_common_guard(w,actor,political_office_resignation_command_kind(c));if(!v.ok)return v;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PoliticalOfficeResignationPlayerCommandRequired");}
}
PoliticalOfficeResignationWorldAccess::PoliticalOfficeResignationWorldAccess(const WorldBundle& w):world_(w),military_(w.political_takeover_enabled()?std::optional<MilitaryAccess>{w.services.military_access()}:std::nullopt),occupations_(w.political_takeover_enabled()?std::optional<PoliticalSuccessionOccupationContext>{PoliticalSuccessionOccupationContext{w.political_takeover,*w.catalog->political_takeover,w.military,*w.catalog->military,*military_}}:std::nullopt),territory_{w.common,w.politics,*w.catalog->politics,*w.catalog->political_successions,occupations_?&*occupations_:nullptr},rules_{w.common,*w.catalog->common,w.politics,*w.catalog->politics,w.organization,*w.catalog->organization,w.local_economy,w.services,*w.catalog->political_successions,*w.catalog->political_office_resignations,*w.political_office_resignations,w.family_death_read(),[this](const PoliticalOfficeResignationPolicy& p,Integer tick,const StableId& fact){return validate_political_office_resignation_seat(territory_,p,tick,fact);},[&w](Integer tick,const StableId& fact){return read_political_office_resignation_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);},w.catalog->director?w.catalog->director->office_resignation_responses.get():nullptr,nullptr}{}
Outcome<std::unique_ptr<PoliticalOfficeResignationWorldAccess>> PoliticalOfficeResignationWorldAccess::create(const WorldBundle& w){auto v=available(w);if(!v.ok)return {false,{},v.error};return {true,std::unique_ptr<PoliticalOfficeResignationWorldAccess>{new PoliticalOfficeResignationWorldAccess(w)},{}};}
// 原Organization、原政治、完整Family/Bio/Legacy和首职全史之后必验来源及永久真实结果。
Status validate_political_office_resignation_world(const WorldBundle& w){auto v=validate_political_office_resignation_layout(w.common,w.catalog->identity.module_versions,w.political_office_resignations?&*w.political_office_resignations:nullptr);if(!v.ok)return v;if(bool(w.catalog->political_office_resignations)!=w.political_office_resignations.has_value())return common_failure("PoliticalOfficeResignationProfileMismatch");if(!w.catalog->political_office_resignations)return common_success();auto read=PoliticalOfficeResignationWorldAccess::create(w);if(!read.ok)return {false,{},read.error};v=validate_political_office_resignation_sources(read.value->context());return v.ok?validate_political_office_resignation_player_results(w.common,*w.political_office_resignations,actual_result):v;}
Outcome<PoliticalOfficeResignationQuote> prepare_political_office_resignation_world(const WorldBundle& w,const StableId& actor,const PoliticalOfficeResignationCommand& c){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto read=PoliticalOfficeResignationWorldAccess::create(w);return read.ok?preview_political_office_resignation(read.value->context(),actor,c):Outcome<PoliticalOfficeResignationQuote>{false,{},read.error};}
Outcome<PoliticsEffects> commit_political_office_resignation_world(WorldBundle& w,const StableId& actor,const PoliticalOfficeResignationCommand& c,const PoliticalOfficeResignationQuote& q){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto read=PoliticalOfficeResignationWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return apply_political_office_resignation_business_in_candidate(w.common,w.organization,*w.political_office_resignations,read.value->context(),actor,c,q);}
Outcome<BoundaryValue> query_political_office_resignation_world(const WorldBundle& w,const StableId& place,Integer cursor){auto read=PoliticalOfficeResignationWorldAccess::create(w);return read.ok?query_political_office_resignations(read.value->context(),place,cursor):Outcome<BoundaryValue>{false,{},read.error};}
Status bind_political_office_resignation_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& r){if(!w.catalog->political_office_resignations||!w.political_office_resignations||source.empty()||!is_political_office_resignation_command(r.kind))return common_failure("PoliticalOfficeResignationNewSourceRequired");return bind_political_office_resignation_player_result(w.common,*w.political_office_resignations,source,actor,request,r,actual_result);}
}
